const variantBySKU = `-- name: VariantBySKU :one
SELECT v.id, p.name AS product_name, COALESCE(co.name, '')::text AS colour, COALESCE(sz.label, '')::text AS size, v.stock
FROM variants v JOIN products p ON p.id = v.product_id
LEFT JOIN colours co ON co.id = v.colour_id
LEFT JOIN sizes sz ON sz.id = v.size_id
WHERE upper(v.sku) = upper($1)
`

type VariantBySKURow struct {
	ID          int64  `json:"id"`
	ProductName string `json:"product_name"`
	Colour      string `json:"colour"`
	Size        string `json:"size"`
	Stock       int32  `json:"stock"`
}

// Staff pick the gift by its SKU.
func (q *Queries) VariantBySKU(ctx context.Context, upper interface{}) (VariantBySKURow, error) {
	row := q.db.QueryRow(ctx, variantBySKU, upper)
	var i VariantBySKURow
	err := row.Scan(
		&i.ID,
		&i.ProductName,
		&i.Colour,
		&i.Size,
		&i.Stock,
	)
	return i, err
}
